package com.example.starter.domain;

/**
 * 周期维保履约义务状态。
 */
public enum ObligationStatus {
    /** 未完成：可派发尝试，或被旧手工维保入口结清 */
    OPEN,
    /** 已终结：已登记一条有效维保记录（尝试双人确认）或手工入口结清 */
    FULFILLED
}

package com.example.starter.domain;

/**
 * 周期维保履约尝试状态。
 */
public enum AttemptStatus {
    /** 进行中：已派发，等待清单完成与双人确认 */
    PLANNED,
    /** 救援抢占挂起：人员已释放、清单保留，可续派新尝试 */
    SUSPENDED,
    /** 双人共同确认完成：已登记有效维保记录并终结义务 */
    COMPLETED,
