        Instant bStart = Instant.parse("2026-01-17T01:00:00Z");
        Resp b = planDispatch("PM-od-b", e1, obId, List.of(s1, s2), twoItems(),
                bStart, Instant.parse("2026-01-17T12:00:00Z"), bStart);
